// بررسی آستانه دما
const temp = msg.payload.value;
const room = msg.payload.room;
let alerts = [];

if (temp > 30) {
    alerts.push({
        type: 'warning',
        message: `دمای ${room} به ${temp} درجه رسید - هشدار دمای بالا`,
        room: room,
        value: temp
    });

    // فعال‌سازی خودکار تهویه اگر در حالت خودکار است
    if (global.get('autoMode') === true) {
        msg.payload = {
            room: room,
            device: 'hvac',
            state: true,
            mode: 'cool',
            temperature: 22,
            auto: true
        };
        return [msg, {payload: alerts[0]}];
    }
}
else if (temp < 15) {
    alerts.push({
        type: 'info',
        message: `دمای ${room} به ${temp} درجه کاهش یافت`,
        room: room,
        value: temp
    });
}

return [null, {payload: alerts.length > 0 ? alerts[0] : null}];

const humidity = msg.payload.value;
const room = msg.payload.room;

if (humidity > 70) {
    msg.payload = {
        type: 'warning',
        message: `رطوبت ${room} به ${humidity}% رسید - هشدار رطوبت بالا`,
        room: room,
        value: humidity
    };
    return msg;
}
return null;

const light = msg.payload.value;
const room = msg.payload.room;
const autoMode = global.get('autoLightMode') || false;

if (light < 300 && autoMode) {
    // فعال‌سازی خودکار روشنایی
    msg.payload = {
        room: room,
        device: 'light',
        state: true,
        brightness: 80,
        auto: true
    };
    return msg;
}
return null;

// بررسی تنظیمات اعلان
const notifySettings = global.get('notificationSettings') || {
    sms: false,
    email: true,
    telegram: true
};

msg.payload.channels = notifySettings;
msg.payload.timestamp = Date.now();

// ذخیره در تاریخچه هشدارها
const alertHistory = context.get('alertHistory') || [];
alertHistory.unshift(msg.payload);
if (alertHistory.length > 100) {
    alertHistory.pop();
}
context.set('alertHistory', alertHistory);

return msg;

// آماده‌سازی پیام برای تلگرام
if (msg.payload.channels.telegram) {
    const botToken = global.get('telegramBotToken') || 'YOUR_BOT_TOKEN';
    const chatId = global.get('telegramChatId') || 'YOUR_CHAT_ID';

    const message = `🚨 *هشدار سیستم هوشمند*

${msg.payload.alert.message}

⏰ زمان: ${new Date(msg.payload.timestamp).toLocaleTimeString('fa-IR')}`;

    // ارسال به تلگرام (در عمل باید از node تلگرام استفاده کنید)
    msg.url = `https://api.telegram.org/bot${botToken}/sendMessage`;
    msg.method = 'POST';
    msg.headers = {'content-type': 'application/json'};
    msg.payload = {
        chat_id: chatId,
        text: message,
        parse_mode: 'Markdown'
    };
    return msg;
}
return null;

// آماده‌سازی ایمیل
if (msg.payload.channels.email) {
    const emailConfig = global.get('emailConfig') || {
        to: 'admin@example.com',
        subject: 'هشدار سیستم هوشمند ساختمان'
    };

    msg.to = emailConfig.to;
    msg.topic = emailConfig.subject;
    msg.payload = `
        <h2>🏠 هشدار سیستم هوشمند</h2>
        <p><strong>پیام:</strong> ${msg.payload.alert.message}</p>
        <p><strong>زمان:</strong> ${new Date(msg.payload.timestamp).toLocaleString('fa-IR')}</p>
        <hr>
        <p>این پیام به صورت خودکار توسط سیستم هوشمند ساختمان ارسال شده است.</p>
    `;
    return msg;
}
return null;

// ذخیره وضعیت فعلی
const room = msg.payload.room;
const currentState = global.get(`light-${room}`) || {};

// به‌روزرسانی وضعیت
currentState.state = msg.payload.state;
currentState.brightness = msg.payload.brightness || 100;
currentState.manual = msg.payload.manual !== false;
currentState.timestamp = Date.now();

global.set(`light-${room}`, currentState);

// ارسال وضعیت به داشبورد
msg.topic = 'home/status';
msg.payload = {
    lights: {
        [room]: msg.payload.state
    },
    timestamp: Date.now()
};

return msg;

// ذخیره وضعیت فعلی
const room = msg.payload.room;
const currentState = global.get(`hvac-${room}`) || {};

// به‌روزرسانی وضعیت
currentState.state = msg.payload.state;
currentState.temperature = msg.payload.temperature || 24;
currentState.mode = msg.payload.mode || 'auto';
currentState.manual = msg.payload.manual !== false;
currentState.timestamp = Date.now();

global.set(`hvac-${room}`, currentState);

// ارسال وضعیت به داشبورد
msg.topic = 'home/status';
msg.payload = {
    hvac: {
        [room]: msg.payload.state
    },
    timestamp: Date.now()
};

return msg;

const action = msg.payload.action;
const messages = [];

if (action === 'morning_routine') {
    // روشن کردن چراغ‌های سالن و تهویه اتاق‌ها
    messages.push({
        topic: 'home/control/light',
        payload: {room: 'living', device: 'light', state: true, brightness: 100, scheduled: true}
    });
    messages.push({
        topic: 'home/control/hvac',
        payload: {room: 'bedroom1', device: 'hvac', state: true, temperature: 23, mode: 'auto', scheduled: true}
    });
    messages.push({
        topic: 'home/control/hvac',
        payload: {room: 'bedroom2', device: 'hvac', state: true, temperature: 23, mode: 'auto', scheduled: true}
    });
}
else if (action === 'evening_routine') {
    // روشنایی کامل و تهویه راحت
    ['living', 'kitchen', 'bedroom1', 'bedroom2'].forEach(room => {
        messages.push({
            topic: 'home/control/light',
            payload: {room: room, device: 'light', state: true, brightness: 90, scheduled: true}
        });
    });
}
else if (action === 'night_routine') {
    // خاموش کردن چراغ‌ها و تهویه شبانه
    ['living', 'kitchen', 'entrance'].forEach(room => {
        messages.push({
            topic: 'home/control/light',
            payload: {room: room, device: 'light', state: false, scheduled: true}
        });
    });
    ['bedroom1', 'bedroom2'].forEach(room => {
        messages.push({
            topic: 'home/control/hvac',
            payload: {room: room, device: 'hvac', state: true, temperature: 22, mode: 'fan', scheduled: true}
        });
    });
}

return messages;
